# -*- coding: utf-8 -*-
"""Rendus partagés : les sorties HTML restent utiles sans JavaScript."""
import portable_io  # Encodage CLI stable, sans dépendance système.
from pathlib import Path
from html import escape as e
import json,re
ROOT=Path(__file__).resolve().parents[1]
def block(html,attribute,value):
 m=re.search(r'<([a-z][a-z0-9]*)\b[^>]*\b'+re.escape(attribute)+r'="'+re.escape(value)+r'"[^>]*>',html,re.I)
 if not m:raise ValueError((attribute,value))
 tag=m[1];depth=0
 for t in re.finditer(r'</?'+tag+r'\b[^>]*>',html[m.start():],re.I):
  depth+=-1 if t[0].startswith('</') else 1
  if depth==0:return html[m.start():m.start()+t.end()]
 raise ValueError('Bloc non fermé : '+value)
def refs(slug,ids=None):
 html=(ROOT/f'articles/{slug}.html').read_text(encoding="utf-8");parts=[]
 for id in re.findall(r'<li id="(ref\d+)"',html):
  if ids is None or id in ids:parts.append(block(html,'id',id).replace('<li id="'+id+'"','<li value="'+id[3:]+'" id="'+id+'"',1))
 return '<section class="resource-sources" aria-labelledby="resource-sources-titre"><h2 id="resource-sources-titre">Sources et accès aux documents</h2><ol>'+''.join(parts)+'</ol><p>Les notices ou liens déjà signalés comme indisponibles restent identifiés comme tels. Une notice n’est pas la lecture intégrale d’un document.</p></section>'
def skin():
 d=json.loads((ROOT/'assets/explorer/structures-peau.json').read_text(encoding="utf-8"))
 buttons=''.join(f'<button type="button" data-structure="{i["id"]}" aria-pressed="false" aria-controls="structure-{i["id"]}">{e(i["title"])}</button>' for i in d)
 panels=''.join(f'<section id="structure-{i["id"]}" data-structure-panel="{i["id"]}"><h3>{e(i["title"])}</h3><p>{e(i["text"])} <a href="{i["source"]}" target="_blank" rel="noopener noreferrer">Source scientifique</a></p></section>' for i in d)
 return '''<section class="cephalo-atlas" id="cephalo-atlas" data-structure-atlas aria-labelledby="cephalo-atlas-titre"><p class="structure-kicker">THOT · Lire un mécanisme</p><h2 id="cephalo-atlas-titre">Pigments, reflets et lumière</h2><p>Des repères fonctionnels, <strong>pas une coupe anatomique universelle</strong>. Les réflecteurs peuvent se trouver sous les chromatophores ; leur répartition varie selon l’espèce et la zone du corps. Les leucophores sont décrits chez des pieuvres et des seiches, généralement absents chez les calmars avec des exceptions. <a href="https://doi.org/10.1098/rsif.2008.0366.focus">Source et limites</a>.</p><div class="skin-cards"><figure><svg viewBox="0 0 240 180" role="img" aria-labelledby="skin-pigment-title"><title id="skin-pigment-title">Repère illustratif : sac de pigment absorbant une partie de la lumière</title><g data-skin-layer="lumiere" stroke="#927038" stroke-width="4"><path d="M35 15L95 70M120 15L125 68M205 15L155 70"/></g><g data-skin-layer="pigments"><path d="M30 88H210M120 35V145M50 45L190 135M50 135L190 45" stroke="#667582" stroke-width="3"/><ellipse cx="120" cy="88" rx="48" ry="30" fill="#9c503e" stroke="#17243a" stroke-width="3"/></g></svg><figcaption>1 · Pigment : absorption</figcaption></figure><figure><svg viewBox="0 0 240 180" role="img" aria-labelledby="skin-irido-title"><title id="skin-irido-title">Repère illustratif : feuillets réfléchissants d’un iridophore</title><g data-skin-layer="iridophores"><path d="M45 70H195M45 85H195M45 100H195M45 115H195" stroke="#245d63" stroke-width="8"/></g><g data-skin-layer="lumiere" fill="none" stroke-width="4"><path d="M50 15L100 65" stroke="#927038"/><path d="M110 65L165 15" stroke="#395fa0"/><path d="M110 80L185 28" stroke="#3a7a64"/></g></svg><figcaption>2 · Structure : reflet sélectif</figcaption></figure><figure><svg viewBox="0 0 240 180" role="img" aria-labelledby="skin-leuco-title"><title id="skin-leuco-title">Repère illustratif : éléments diffusants d’un leucophore</title><g data-skin-layer="leucophores" fill="#fffefa" stroke="#667582" stroke-width="3"><circle cx="85" cy="90" r="17"/><circle cx="125" cy="85" r="21"/><circle cx="155" cy="110" r="18"/><circle cx="110" cy="125" r="16"/></g><g data-skin-layer="lumiere" fill="none" stroke="#927038" stroke-width="4"><path d="M120 10V52M90 45L65 20M150 45L185 20M60 90H25M178 90H215"/></g></svg><figcaption>3 · Structure : diffusion</figcaption></figure></div><p class="structure-limit">Dessins THOT qualitatifs, non à l’échelle. Les couleurs, nombres d’éléments et flèches sont illustratifs. Ils ne calculent ni une teinte biologique ni une trajectoire réelle de lumière. <a href="#chromato-modele">Manipuler le sac pigmentaire existant</a>.</p><div class="structure-controls" hidden><div class="structure-choices" role="group" aria-label="Choisir un mécanisme">'''+buttons+'''</div><fieldset class="structure-layers"><legend>Afficher ou masquer les repères dessinés</legend>'''+''.join(f'<label><input type="checkbox" data-skin-toggle="{id}" checked> {label}</label>' for id,label in [('pigments','Pigments'),('iridophores','Reflets sélectifs'),('leucophores','Diffusion'),('lumiere','Lumière')])+'''</fieldset></div><p class="structure-status" role="status" aria-live="polite" aria-atomic="true"></p><div class="structure-explanations">'''+panels+'''</div><noscript><p>Les sept explications sont disponibles en lecture continue ; les commandes de sélection sont masquées.</p></noscript></section>'''
